DG.put("ath-pakhyaan-charitr-likhyate/109",{"n":109,"title":null,"title_roman":null,"page":1437,"blocks":[{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1437,"meaning_status":"draft"},{"type":"verse","number":[1],"number_text":"੧।","page":1437,"lines":[{"gurmukhi":"ਯਹ ਚਲਿ ਖਬਰ ਜਾਤ ਭੀ ਤਹਾ। ਬੈਠੀ ਸਭਾ ਧਰਮੁ ਕੀ ਜਹਾ।","roman":"Yah chali khabar jaat bhee tahaa | baithee sabhaa dharmu kee jahaa |","meaning_en":"This news travelled to where the court of Dharam (Dharamraj) was sitting:","page":1437,"meaning_status":"draft","note":"ਧਰਮੁ ਕੀ ਸਭਾ: the court of Dharamraj, the judge of the dead."},{"gurmukhi":"ਸਵਤਿ ਸਾਲ ਤਿਨ ਤ੍ਰਿਯਹਿ ਨਿਹਾਰਿਯੋ। ਨਿਜੁ ਪਤਿ ਬਾਨ ਸਾਥ ਹਨਿ ਡਾਰਿਯੋ। ੧।","roman":"Savti saal tin triyhi nihaariyo | niju pati baan saath hani daariyo | 1 |","meaning_en":"they saw how that woman, out of the pain of a co-wife, had killed her own husband with an arrow.","page":1437,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਧਰਮਰਾਇ ਬਾਚ","gurmukhi":"ਧਰਮਰਾਇ ਬਾਚ","roman":"Dharamraai baach","meaning_en":"Dharamrai said:","page":1437,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1437,"meaning_status":"draft"},{"type":"verse","number":[2],"number_text":"੨।","page":1437,"lines":[{"gurmukhi":"ਜਾ ਦੁਖ ਤੇ ਜਿਨ ਇਸਤ੍ਰਿਯਹਿ ਨਿਜੁ ਪਤਿ ਹਨਿਯੋ ਰਿਸਾਇ।","roman":"Jaa dukh te jin istriyhi niju pati haniyo risaai |","meaning_en":"'Through the same pain by which this woman in anger killed her own husband,","page":1437,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਦੁਖ ਤੇ ਤਿਹ ਮਾਰਿਯੈ ਕਰਿਯੈ ਵਹੈ ਉਪਾਇ। ੨।","roman":"Taa dukh te tih maariyai kariyai vahai upaai | 2 |","meaning_en":"through that pain she should be killed; let such a means be found.'","page":1437,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1439,"meaning_status":"draft"},{"type":"verse","number":[3],"number_text":"੩।","page":1439,"lines":[{"gurmukhi":"ਉਰਬਸਿ ਪ੍ਰਾਤ ਹੁਤੀ ਸੁ ਨਗਰ ਮੈ। ਨਾਚਤ ਹੁਤੀ ਕਾਲ ਕੇ ਘਰ ਮੈ।","roman":"Urabsi praat hutee su nagar mai | naachat hutee kaal ke ghar mai |","meaning_en":"Urvashi was in that city in the morning, dancing in the house of Kaal (Death).","page":1439,"meaning_status":"draft","note":"ਉਰਬਸਿ: Urvashi, a celestial dancer. ਕਾਲ ਕੇ ਘਰ: the house of Death, i.e. Dharamraj's court."},{"gurmukhi":"ਤਿਹ ਬੀਰੋ ਤਿਹ ਸਭਾ ਉਚਾਯੋ। ਸਕਲ ਪੁਰਖ ਕੋ ਭੇਖ ਬਣਾਯੋ। ੩।","roman":"Tih beero tih sabhaa uchaayo | sakal purakh ko bhekh banaayo | 3 |","meaning_en":"She took up the betel-roll in that court and put on the full dress of a man.","page":1439,"meaning_status":"draft","note":"ਬੀਰੋ ਉਚਾਯੋ: 'took up the betel-roll', i.e. accepted the task as a challenge."}]},{"type":"heading","kind":"speaker","name":"ਉਰਬਸੀ ਬਾਚ","gurmukhi":"ਉਰਬਸੀ ਬਾਚ","roman":"Urabsee baach","meaning_en":"Urvashi said:","page":1439,"meaning_status":"draft"},{"type":"verse","number":[4],"number_text":"੪।","page":1439,"lines":[{"gurmukhi":"ਮੁਸਕਿਲ ਹਨਨ ਤਵਨ ਕੋ ਗੁਨਿਯੈ। ਜਾ ਕੋ ਅਧਿਕ ਸੀਲ ਜਗੁ ਸੁਨਿਯੈ।","roman":"Muskil hanan tavan ko guniyai | jaa ko adhik seel jagu suniyai |","meaning_en":"'Count it hard to destroy one whose great modesty the world has heard of;","page":1439,"meaning_status":"draft","note":"ਸੀਲ: modesty, virtue."},{"gurmukhi":"ਜਾ ਕੋ ਚਿਤ ਚੰਚਲ ਪਹਿਚਾਨਹੁ। ਤਾ ਕੋ ਲਈ ਹਾਥ ਮੈ ਮਾਨਹੁ। ੪।","roman":"Jaa ko chit chanchal pahichaanhu | taa ko laee haath mai maanhu | 4 |","meaning_en":"but one whose heart you recognise as fickle, consider her already taken in hand.'","page":1439,"meaning_status":"draft"}]},{"type":"verse","number":[5],"number_text":"੫।","page":1439,"lines":[{"gurmukhi":"ਯੌ ਕਹਿ ਨਿਕਸਿ ਮੋਲ ਹਯ ਲਯੋ। ਜਾ ਪੈ ਲਾਖ ਟਕਾ ਦਸ ਦਯੋ।","roman":"Yau kahi niksi mol hay layo | jaa pai laakh takaa das dayo |","meaning_en":"Saying this she went out and bought a horse, for which she paid ten lakh takas.","page":1439,"meaning_status":"draft"},{"gurmukhi":"ਚਮਕਿ ਚਲੈ ਜਬ ਤੁਰੇ ਬਿਰਾਜੈ। ਜਾ ਕੋ ਨਿਰਖਿ ਇੰਦ੍ਰ ਹਯ ਲਾਜੈ। ੫।","roman":"Chamki chalai jab ture biraajai | jaa ko nirkhi indr hay laajai | 5 |","meaning_en":"When it moved, the horse gleamed and shone; seeing it, Indra's horse would be put to shame.","page":1439,"meaning_status":"draft"}]},{"type":"verse","number":[6],"number_text":"੬।","page":1439,"lines":[{"gurmukhi":"ਆਪ ਅਨੂਪ ਬਸਤ੍ਰ ਤਨ ਧਾਰੈ। ਭੂਖਨ ਸਕਲ ਜਰਾਇ ਸੁ ਧਾਰੈ।","roman":"Aap anoop basatr tan dhaarai | bhookhan sakal jaraai su dhaarai |","meaning_en":"She put matchless clothes on her body and wore all her jewelled ornaments.","page":1439,"meaning_status":"draft"},{"gurmukhi":"ਲਾਂਬੇ ਕੇਸ ਕਾਂਧ ਪਰ ਛੋਰੇ। ਜਨੁਕ ਫੁਲੇਲਹਿ ਜਾਤ ਨਿਚੋਰੇ। ੬।","roman":"Laanbe kes kaandh par chhore | januk phulelhi jaat nichore | 6 |","meaning_en":"She let her long hair loose over her shoulders, as if perfumed oil were being wrung from it.","page":1439,"meaning_status":"draft","note":"ਫੁਲੇਲ: perfumed hair-oil."}]},{"type":"verse","number":[7],"number_text":"੭।","page":1439,"lines":[{"gurmukhi":"ਅੰਜਨ ਆਂਜਿ ਆਖਿਯਨ ਦਯੋ। ਜਨੁ ਕਰਿ ਲੂਟਿ ਸਿੰਗਾਰਹਿ ਲਯੋ।","roman":"Anjan aanji aakhiyan dayo | janu kari looti singaarhi layo |","meaning_en":"She put kohl in her eyes, as if she had plundered adornment itself.","page":1439,"meaning_status":"draft"},{"gurmukhi":"ਜੁਲਫ ਜੰਜੀਰ ਜਾਲਮੈ ਸੋਹੈ। ਸੁਰ ਨਰ ਨਾਗ ਅਸੁਰ ਮਨ ਮੋਹੈ। ੭।","roman":"Julaph janjeer jaalmai sohai | sur nar naag asur man mohai | 7 |","meaning_en":"Her cruel chain-like locks shone, and charmed the hearts of gods, men, nagas and demons.","page":1439,"meaning_status":"draft","note":"ਜੁਲਫ ਜੰਜੀਰ ਜਾਲਮੈ: read as 'tyrannous chains of locks' (Persian zulf, zanjir, zalim); uncertain."}]},{"type":"verse","number":[8],"number_text":"੮।","page":1439,"lines":[{"gurmukhi":"ਰਾਜਤ ਭ੍ਰਿਕੁਟਿ ਧਨੁਕ ਸੀ ਭਾਰੀ। ਮੋਹਤ ਲੋਕ ਚੌਦਹਨਿ ਪ੍ਯਾਰੀ।","roman":"Raajat bhrikuti dhanuk see bhaaree | mohat lok chaudahni pyaaree |","meaning_en":"Her eyebrows shone like great bows; the lovely one charmed the fourteen worlds.","page":1439,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਕੀ ਨੈਕ ਦ੍ਰਿਸਟਿ ਮੈ ਪਰੈ। ਤਾ ਕੀ ਸਕਲ ਬੁਧਿ ਪਰਹਰੇ। ੮।","roman":"Jaa kee naik dristi mai parai | taa kee sakal budhi parahre | 8 |","meaning_en":"Whoever came even a little into her sight lost all his wits.","page":1439,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1439,"meaning_status":"draft"},{"type":"verse","number":[9],"number_text":"੯।","page":1439,"lines":[{"gurmukhi":"ਖਟਮੁਖ ਮੁਖ ਖਟ ਪੰਚ ਸਿਵ ਬਿਧਿ ਕੀਨੇ ਮੁਖ ਚਾਰਿ।","roman":"Khatmukh mukh khat panch siv bidhi keene mukh chaari |","meaning_en":"The six-faced one (Kartikeya) made six faces, Shiva five, and Brahma made four faces;","page":1439,"meaning_status":"draft","note":"ਖਟਮੁਖ: Kartikeya, son of Shiva. ਬਿਧਿ: Brahma."},{"gurmukhi":"ਉਰਬਸਿ ਕੇਰੇ ਰੂਪ ਕੋ ਤਊ ਨ ਪਾਯੋ ਪਾਰ। ੯।","roman":"Urabsi kere roop ko taoo na paayo paar | 9 |","meaning_en":"even so they could not find the limit of Urvashi's beauty.","page":1439,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1439,"meaning_status":"draft"},{"type":"verse","number":[10],"number_text":"੧੦।","page":1439,"lines":[{"gurmukhi":"ਆਯੁਧ ਸਕਲ ਅੰਗ ਕਰੇ। ਸੋਹਤ ਸਭ ਸਾਜਨ ਸੌ ਜਰੇ।","roman":"Aayudh sakal ang kare | sohat sabh saajan sau jare |","meaning_en":"She put all her weapons on her body; she shone, set with all her equipment.","page":1439,"meaning_status":"draft"},{"gurmukhi":"ਹੀਰਨ ਕੀ ਮੁਕਤਾ ਜਗ ਸੋਹੈ। ਸਸਿ ਕੋ ਮਨੋ ਤਾਰਿਕਾ ਮੋਹੈ। ੧੦।","roman":"Heeran kee muktaa jag sohai | sasi ko mano taarikaa mohai | 10 |","meaning_en":"Her diamonds and pearls glittered, as if the stars were charming the moon.","page":1439,"meaning_status":"draft","note":"ਜਗ: read as 'glittering' (ਜਗਮਗ); uncertain."}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":1439,"meaning_status":"draft"},{"type":"verse","number":[11],"number_text":"੧੧।","page":1439,"lines":[{"gurmukhi":"ਆਯੁਧ ਧਾਰਿ ਅਨੂਪਮ ਸੁੰਦਰਿ ਭੂਖਨ ਅੰਗ ਅਜਾਇਬ ਧਾਰੇ।","roman":"Aayudh dhaari anoopam sundri bhookhan ang ajaaib dhaare |","meaning_en":"Bearing weapons, the matchless beauty wore wondrous ornaments on her limbs.","page":1439,"meaning_status":"draft","note":"ਅਜਾਇਬ: Persian 'wondrous'."},{"gurmukhi":"ਲਾਲ ਕੋ ਹਾਰ ਲਸੈ ਉਰ ਭੀਤਰਿ ਭਾਨ ਤੇ ਜਾਨੁ ਬਡੇ ਛਬਿਯਾਰੇ।","roman":"Laal ko haar lasai ur bheetri bhaan te jaanu bade chhabiyaare |","meaning_en":"A necklace of rubies shone on her breast, more radiant, it seemed, than the sun.","page":1439,"meaning_status":"draft"},{"gurmukhi":"ਮੋਤਿਨ ਕੀ ਲਰਕੈ ਮੁਖ ਪੈ ਮ੍ਰਿਗਨੈਨਿ ਫਬੇ ਮ੍ਰਿਗ ਸੇ ਕਜਰਾਰੇ।","roman":"Motin kee larkai mukh pai mrignaini phabe mrig se kajraare |","meaning_en":"Strings of pearls hung over her face; the doe-eyed one's kohl-darkened eyes looked lovely, like a deer's.","page":1439,"meaning_status":"draft"},{"gurmukhi":"ਮੋਹਤ ਹੈ ਸਭ ਹੀ ਕੇ ਚਿਤੈ ਨਿਜ ਹਾਥ ਮਨੋ ਬ੍ਰਿਜਨਾਥ ਸੁਧਾਰੇ। ੧੧।","roman":"Mohat hai sabh hee ke chitai nij haath mano brijnaath sudhaare | 11 |","meaning_en":"She charmed everyone's heart, as if the Lord of Braj (Krishna) had fashioned her with his own hands.","page":1439,"meaning_status":"draft","note":"ਬ੍ਰਿਜਨਾਥ: Lord of Braj, Krishna."}]},{"type":"verse","number":[12],"number_text":"੧੨।","page":1441,"lines":[{"gurmukhi":"ਛੋਰਿ ਦਏ ਕਚ ਕਾਂਧਨ ਊਪਰ ਸੁੰਦਰ ਪਾਗ ਸੌ ਸੀਸ ਸੁਹਾਵੈ।","roman":"Chhori dae kach kaandhan oopar sundar paag sau sees suhaavai |","meaning_en":"She let her hair loose over her shoulders; her head looked lovely with a fine turban.","page":1441,"meaning_status":"draft"},{"gurmukhi":"ਭੂਖਨ ਚਾਰੁ ਲਸੈ ਸਭ ਅੰਗਨ ਭਾਗ ਭਰਿਯੋ ਸਭ ਹੀ ਕਹ ਭਾਵੈ।","roman":"Bhookhan chaaru lasai sabh angan bhaag bhariyo sabh hee kah bhaavai |","meaning_en":"Beautiful ornaments shone on all her limbs; full of good fortune, she pleased everyone.","page":1441,"meaning_status":"draft"},{"gurmukhi":"ਬਾਲ ਲਖੈ ਕਹਿ ਲਾਲ ਤਿਸੈ ਲਟਕਾਵਤ ਅੰਗਨ ਮੈ ਜਬ ਆਵੈ।","roman":"Baal lakhai kahi laal tisai latkaavat angan mai jab aavai |","meaning_en":"When she came swaying into the courtyard, the women saw her and called her 'darling'.","page":1441,"meaning_status":"draft"},{"gurmukhi":"ਰੀਝਤ ਕੋਟਿ ਸੁਰੀ ਅਸੁਰੀ ਸੁਧਿ ਹੇਰਿ ਛੁਟੈ ਸਤ ਹੂ ਛੁਟ ਜਾਵੈ। ੧੨।","roman":"Reejhat koti suree asuree sudhi heri chhutai sat hoo chhut jaavai | 12 |","meaning_en":"Millions of goddesses and demon women were charmed; seeing her they lost their senses, and even their virtue left them.","page":1441,"meaning_status":"draft","note":"ਸਤ: chastity, virtue."}]},{"type":"verse","number":[13],"number_text":"੧੩।","page":1441,"lines":[{"gurmukhi":"ਭੂਖਨ ਧਾਰਿ ਚੜਿਯੋ ਰਥ ਊਪਰਿ ਬਾਧਿ ਕ੍ਰਿਪਾਨ ਨਿਖੰਗ ਬਨਾਯੋ।","roman":"Bhookhan dhaari chariyo rath oopri baadhi kripaan nikhang banaayo |","meaning_en":"Wearing her ornaments she mounted the chariot, fastening on her sword and fitting her quiver.","page":1441,"meaning_status":"draft"},{"gurmukhi":"ਖਾਤ ਤੰਬੋਲ ਬਿਰਾਜਤ ਸੁੰਦਰ ਦੇਵ ਅਦੇਵਨ ਕੋ ਬਿਰਮਾਯੋ।","roman":"Khaat tanbol biraajat sundar dev adevan ko birmaayo |","meaning_en":"Chewing betel the beautiful one shone; she beguiled gods and demons.","page":1441,"meaning_status":"draft"},{"gurmukhi":"ਬਾਸ ਵ ਨੈਨ ਸਹੰਸ੍ਰਨ ਸੌ ਛਬਿ ਹੇਰਿ ਰਹਿਯੋ ਕਛੁ ਪਾਰ ਨ ਪਾਯੋ।","roman":"Baas va nain sahansran sau chhabi heri rahiyo kachhu paar na paayo |","meaning_en":"Basav (Indra) kept gazing at her beauty with his thousand eyes, but found no end to it.","page":1441,"meaning_status":"draft","note":"ਬਾਸ ਵ: printed with a space; read as ਬਾਸਵ, Indra."},{"gurmukhi":"ਆਪੁ ਬਨਾਇ ਅਨੂਪਮ ਕੋ ਬਿਧਿ ਐਚਿ ਰਹਿਯੋ ਦੁਤਿ ਅੰਤ ਨ ਪਾਯੋ। ੧੩।","roman":"Aapu banaai anoopam ko bidhi aichi rahiyo duti ant na paayo | 13 |","meaning_en":"The Creator, who had himself made this matchless one, was left spellbound and found no end to her radiance.","page":1441,"meaning_status":"draft","note":"ਐਚਿ ਰਹਿਯੋ: 'was drawn, held'; uncertain."}]},{"type":"verse","number":[14],"number_text":"੧੪।","page":1441,"lines":[{"gurmukhi":"ਪਾਨ ਚਬਾਇ ਭਲੀ ਬਿਧਿ ਸਾਥ ਜਰਾਇ ਜਰੈ ਹਥਿਯਾਰ ਬਨਾਏ।","roman":"Paan chabaai bhalee bidhi saath jaraai jarai hathiyaar banaae |","meaning_en":"Chewing betel, she fittingly equipped herself with jewelled weapons.","page":1441,"meaning_status":"draft"},{"gurmukhi":"ਅੰਜਨ ਆਂਜਿ ਅਨੂਪਮ ਸੁੰਦਰਿ ਦੇਵ ਅਦੇਵ ਸਭੈ ਬਿਰਮਾਏ।","roman":"Anjan aanji anoopam sundri dev adev sabhai birmaae |","meaning_en":"Putting on kohl, the matchless beauty beguiled all the gods and demons.","page":1441,"meaning_status":"draft"},{"gurmukhi":"ਕੰਠ ਸਿਰੀਮਨਿ ਕੰਕਨ ਕੁੰਡਲ ਹਾਰ ਸੁ ਨਾਰਿ ਹੀਏ ਪਹਿਰਾਏ।","roman":"Kanth sireemni kankan kundal haar su naari hee'e pahiraae |","meaning_en":"A crest-jewel at her throat, bracelets, earrings and necklaces the woman put on her breast.","page":1441,"meaning_status":"draft","note":"ਸਿਰੀਮਨਿ: a crest-jewel, an ornament."},{"gurmukhi":"ਕਿੰਨਰ ਜਛ ਭੁਜੰਗ ਦਿਸਾ ਬਿਦਿਸਾਨ ਕੈ ਲੋਕ ਬਿਲੋਕਿਨ ਆਏ। ੧੪।","roman":"Kinnar jachh bhujang disaa bidisaan kai lok bilokin aae | 14 |","meaning_en":"Kinnars, yakshas and nagas came from every direction and quarter to look at her.","page":1441,"meaning_status":"draft","note":"ਕਿੰਨਰ, ਜਛ, ਭੁਜੰਗ: classes of semi-divine beings and serpent beings."}]},{"type":"verse","number":[15],"number_text":"੧੫।","page":1441,"lines":[{"gurmukhi":"ਇੰਦ੍ਰ ਸਹੰਸ੍ਰ ਬਿਲੋਚਨ ਸੌ ਅਵਿਲੋਕ ਰਹਿਯੋ ਛਬਿ ਅੰਤੁ ਨ ਆਯੋ।","roman":"Indr sahansr bilochan sau avilok rahiyo chhabi antu na aayo |","meaning_en":"Indra kept gazing with his thousand eyes, but did not reach the end of her beauty.","page":1441,"meaning_status":"draft"},{"gurmukhi":"ਸੇਖ ਅਸੇਖਨ ਹੀ ਮੁਖ ਸੌ ਗੁਨ ਭਾਖਿ ਰਹੋ ਪਰੁ ਪਾਰ ਨ ਪਾਯੋ।","roman":"Sekh asekhan hee mukh sau gun bhaakhi raho paru paar na paayo |","meaning_en":"Shesh kept telling her qualities with all his countless mouths, but found no limit.","page":1441,"meaning_status":"draft","note":"ਸੇਖ: Sheshnag, the thousand-headed serpent."},{"gurmukhi":"ਰੁਦ੍ਰ ਪਿਯਾਰੀ ਕੀ ਸਾਰੀ ਕੀ ਕੋਰ ਨਿਹਾਰਨ ਕੌ ਮੁਖ ਪੰਚ ਬਨਾਯੋ।","roman":"Rudr piyaaree kee saaree kee kor nihaaran kau mukh panch banaayo |","meaning_en":"Rudra made himself five faces to gaze at the border of the lovely one's sari;","page":1441,"meaning_status":"draft","note":"ਰੁਦ੍ਰ ਪਿਯਾਰੀ ਕੀ: read as 'Rudra (gazing at) the beloved's'; it may also be read 'of Rudra's beloved'. Uncertain."},{"gurmukhi":"ਪੂਤ ਕਿਯੇ ਖਟ ਚਾਰਿ ਬਿਧੈ ਚਤੁਰਾਨਨ ਯਾਹੀ ਤੇ ਨਾਮੁ ਕਹਾਯੋ। ੧੫।","roman":"Poot kiye khat chaari bidhai chaturaanan yaahee te naamu kahaayo | 15 |","meaning_en":"the son (Kartikeya) made six and the Creator four; that is why he is called Chaturanan (Four-faced).","page":1441,"meaning_status":"draft","note":"ਪੂਤ: the son, read as Kartikeya, son of Shiva."}]},{"type":"verse","number":[16],"number_text":"੧੬।","page":1441,"lines":[{"gurmukhi":"ਕੰਚਨ ਕੀਰ ਕਲਾਨਿਧਿ ਕੇਹਰ ਕੋਕ ਕਪੋਤ ਕਰੀ ਕੁਰਰਾਨੇ।","roman":"Kanchan keer kalaanidhi kehar kok kapot karee kurraane |","meaning_en":"Gold, the parrot, the moon, the lion, the chakva, the dove, the elephant and the kurra,","page":1441,"meaning_status":"draft","note":"These are the traditional objects to which a beauty's features are compared (complexion, nose, face, waist, breasts, neck, gait, and so on). ਕੋਕ: the chakva bird. ਕੁਰਰਾ: a kind of bird; uncertain."},{"gurmukhi":"ਕਲਪਦ੍ਰੁਮਕਾ ਅਨੁਜਾ ਕਮਨੀ ਬਿਨੁ ਦਾਰਿਮ ਦਾਮਨਿ ਦੇਖਿ ਬਿਕਾਨੇ।","roman":"Kalapdrumkaa anujaa kamnee binu daarim daamni dekhi bikaane |","meaning_en":"the lovely younger sister of the wish-tree, the pomegranate and the lightning, seeing her, were sold without price.","page":1441,"meaning_status":"draft","note":"ਕਲਪਦ੍ਰੁਮ ਕਾ ਅਨੁਜਾ: 'younger sister of the wish-tree', perhaps Lakshmi, who also rose from the churned ocean; uncertain. ਬਿਨੁ ... ਬਿਕਾਨੇ: read as 'sold without price'."},{"gurmukhi":"ਰੀਝਤ ਦੇਵ ਅਦੇਵ ਸਭੈ ਨਰ ਦੇਵ ਭਏ ਛਬਿ ਹੇਰਿ ਦਿਵਾਨੇ।","roman":"Reejhat dev adev sabhai nar dev bhae chhabi heri divaane |","meaning_en":"All the gods and demons were charmed; kings went mad on seeing her beauty.","page":1441,"meaning_status":"draft"},{"gurmukhi":"ਰਾਜ ਕੁਮਾਰ ਸੋ ਜਾਨਿ ਪਰੈ ਤਿਹ ਬਾਲ ਕੇ ਅੰਗ ਨ ਜਾਤ ਪਛਾਨੇ। ੧੬।","roman":"Raaj kumaar so jaani parai tih baal ke ang na jaat pachhaane | 16 |","meaning_en":"She seemed a prince; the girl's body could not be recognised (as a woman's).","page":1441,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1441,"meaning_status":"draft"},{"type":"verse","number":[17],"number_text":"੧੭।","page":1441,"lines":[{"gurmukhi":"ਦਸ ਸੀਸਨ ਰਾਵਨ ਰਰੇ ਲਿਖਤ ਬੀਸ ਭੁਜ ਜਾਇ।","roman":"Das seesan raavan rare likhat bees bhuj jaai |","meaning_en":"Even if Ravan recited with his ten heads and wrote with his twenty arms,","page":1441,"meaning_status":"draft"},{"gurmukhi":"ਤਰੁਨੀ ਕੇ ਤਿਲ ਕੀ ਤਊ ਸਕ੍ਯੋ ਨ ਛਬਿ ਕੋ ਪਾਇ। ੧੭।","roman":"Tarunee ke til kee taoo sakyo na chhabi ko paai | 17 |","meaning_en":"he still could not capture the beauty of the young woman's mole.","page":1441,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":1441,"meaning_status":"draft"},{"type":"verse","number":[18],"number_text":"੧੮।","page":1441,"lines":[{"gurmukhi":"ਲਾਲਨ ਕੋ ਸਰਪੇਚ ਬਧ੍ਯੋ ਸਿਰ ਮੋਤਿਨ ਕੀ ਉਰ ਮਾਲ ਬਿਰਾਜੈ।","roman":"Laalan ko sarpech badhyo sir motin kee ur maal biraajai |","meaning_en":"A turban-jewel of rubies was tied on her head, and a string of pearls shone on her breast.","page":1441,"meaning_status":"draft","note":"ਸਰਪੇਚ: a jewelled ornament worn on the turban."},{"gurmukhi":"ਭੂਖਨ ਚਾਰੁ ਦਿਪੈ ਅਤਿ ਹੀ ਦੁਤਿ ਦੇਖਿ ਮਨੋਜਵ ਕੋ ਮਨੁ ਲਾਜੈ।","roman":"Bhookhan chaaru dipai ati hee duti dekhi manojav ko manu laajai |","meaning_en":"Her lovely ornaments gleamed brightly; seeing their splendour, Kama's heart was ashamed.","page":1441,"meaning_status":"draft","note":"ਮਨੋਜਵ: read as Manoj, Kama."},{"gurmukhi":"ਮੋਦ ਬਢੈ ਨਿਰਖੇ ਚਿਤ ਮੈ ਤਨਿਕੇਕ ਬਿਖੈ ਤਨ ਕੋ ਦੁਖ ਭਾਜੈ।","roman":"Mod badhai nirkhe chit mai tanikek bikhai tan ko dukh bhaajai |","meaning_en":"Seeing her, joy grew in the heart, and in a moment the body's pain fled.","page":1441,"meaning_status":"draft"},{"gurmukhi":"ਜੋਬਨ ਜੋਤਿ ਜਗੈ ਸੁ ਮਨੋ ਸੁਰਰਾਜ ਸੁਰਾਨ ਕੇ ਭੀਤਰ ਰਾਜੈ। ੧੮।","roman":"Joban joti jagai su mano surraaj suraan ke bheetar raajai | 18 |","meaning_en":"The light of youth shone, as though the king of the gods shone among the gods.","page":1441,"meaning_status":"draft"}]},{"type":"verse","number":[19],"number_text":"੧੯।","page":1443,"lines":[{"gurmukhi":"ਛੋਰੈ ਹੈ ਬੰਦ ਅਨੂਪਮ ਸੁੰਦਰਿ ਪਾਨ ਚਬਾਇ ਸਿੰਗਾਰ ਬਨਾਯੋ।","roman":"Chhorai hai band anoopam sundri paan chabaai singaar banaayo |","meaning_en":"The matchless beauty loosened her ties, chewed betel and made her adornment.","page":1443,"meaning_status":"draft","note":"ਛੋਰੈ ਹੈ ਬੰਦ: 'loosened the fastenings' (of the coat or turban); uncertain."},{"gurmukhi":"ਅੰਜਨ ਆਂਜਿ ਦੁਹੂੰ ਅਖਿਯਾਨ ਸੁ ਭਾਲ ਮੈ ਕੇਸਰਿ ਲਾਲ ਲਗਾਯੋ।","roman":"Anjan aanji duhoon akhiyaan su bhaal mai kesri laal lagaayo |","meaning_en":"She put kohl in both her eyes and a red saffron mark on her forehead.","page":1443,"meaning_status":"draft"},{"gurmukhi":"ਝੂਮਕ ਦੇਤ ਝੁਕੈ ਝੁਮਕੇ ਕਬਿ ਰਾਮ ਸੁ ਭਾਵ ਭਲੋ ਲਖਿ ਪਾਯੋ।","roman":"Jhoomak det jhukai jhumke kabi raam su bhaav bhalo lakhi paayo |","meaning_en":"Her pendant earrings swing and sway; the poet Ram has perceived a fine fancy in this:","page":1443,"meaning_status":"draft","note":"ਕਬਿ ਰਾਮ: the poet's name Ram."},{"gurmukhi":"ਮਾਨਹੁ ਸੌਤਿਨ ਕੇ ਮਨ ਕੋ ਇਕ ਬਾਰਹਿ ਬਾਧਿ ਕੈ ਜੇਲ ਚਲਾਯੋ। ੧੯।","roman":"Maanhu sautin ke man ko ik baarhi baadhi kai jel chalaayo | 19 |","meaning_en":"as if she had bound the hearts of her rivals all at once and marched them off to jail.","page":1443,"meaning_status":"draft","note":"ਸੌਤਿਨ: co-wives, rival women. ਜੇਲ: jail."}]},{"type":"verse","number":[20],"number_text":"੨੦।","page":1443,"lines":[{"gurmukhi":"ਹਾਰ ਸਿੰਗਾਰ ਕਰੋ ਸਭ ਹੀ ਤਿਨ ਕੇਸ ਛੁਟੇ ਸਿਰ ਸ੍ਯਾਮ ਸੁਹਾਵੈ।","roman":"Haar singaar karo sabh hee tin kes chhute sir syaam suhaavai |","meaning_en":"She put on all her necklaces and adornment; her loose dark hair looked lovely on her head.","page":1443,"meaning_status":"draft"},{"gurmukhi":"ਜੋਬਨ ਜੋਤਿ ਜਗੈ ਅਤਿ ਹੀ ਮੁਨਿ ਹੇਰਿ ਡਿਗੈ ਤਪ ਤੇ ਪਛੁਤਾਵੈ।","roman":"Joban joti jagai ati hee muni heri digai tap te pachhutaavai |","meaning_en":"The light of her youth shone so brightly that sages, seeing her, fell from their austerities and regretted it.","page":1443,"meaning_status":"draft"},{"gurmukhi":"ਕਿੰਨਰ ਜਛ ਭੁਜੰਗ ਦਿਸਾ ਬਿਦਿਸਾਨ ਕੀ ਬਾਲ ਬਿਲੋਕਨ ਆਵੈ।","roman":"Kinnar jachh bhujang disaa bidisaan kee baal bilokan aavai |","meaning_en":"The women of the kinnars, yakshas and nagas came from every direction and quarter to see her.","page":1443,"meaning_status":"draft"},{"gurmukhi":"ਗੰਧ੍ਰਬ ਦੇਵ ਅਦੇਵਨ ਕੀ ਤ੍ਰਿਯ ਹੇਰਿ ਪ੍ਰਭਾ ਸਭ ਹੀ ਬਲ ਜਾਵੈ। ੨੦।","roman":"Gandhrab dev adevan kee triy heri prabhaa sabh hee bal jaavai | 20 |","meaning_en":"The wives of the gandharvas, gods and demons, seeing her splendour, all offered themselves to her.","page":1443,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1443,"meaning_status":"draft"},{"type":"verse","number":[21],"number_text":"੨੧।","page":1443,"lines":[{"gurmukhi":"ਐਸੋ ਭੇਖ ਬਨਾਇ ਕੈ ਤਹ ਤੇ ਕਰਿਯੋ ਪਿਯਾਨ।","roman":"Aiso bhekh banaai kai tah te kariyo piyaan |","meaning_en":"Putting on such a guise, she set out from there;","page":1443,"meaning_status":"draft"},{"gurmukhi":"ਪਲਕ ਏਕ ਬੀਤੀ ਨਹੀ ਤਹਾ ਪਹੂੰਚੀ ਆਨਿ। ੨੧।","roman":"Palak ek beetee nahee tahaa pahoonchee aani | 21 |","meaning_en":"not even a moment passed before she arrived there.","page":1443,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1443,"meaning_status":"draft"},{"type":"verse","number":[22],"number_text":"੨੨।","page":1443,"lines":[{"gurmukhi":"ਏਤੀ ਕਥਾ ਸੁ ਯਾ ਪੈ ਭਈ। ਅਬ ਕਥ ਚਲਿ ਤਿਹ ਤ੍ਰਿਯ ਪੈ ਗਈ।","roman":"Etee kathaa su yaa pai bhaee | ab kath chali tih triy pai gaee |","meaning_en":"So much of the story concerned her; now the story turns to that woman","page":1443,"meaning_status":"draft"},{"gurmukhi":"ਨਿਜੁ ਪਤਿ ਮਾਰਿ ਰਾਜ ਜਿਨ ਲਯੋ। ਲੈ ਸੁ ਛਤ੍ਰੁ ਨਿਜੁ ਸੁਤ ਸਿਰ ਦਯੋ। ੨੨।","roman":"Niju pati maari raaj jin layo | lai su chhatru niju sut sir dayo | 22 |","meaning_en":"who had killed her husband and taken the kingdom, and had taken the royal canopy and set it over her son's head.","page":1443,"meaning_status":"draft"}]},{"type":"verse","number":[23],"number_text":"੨੩।","page":1443,"lines":[{"gurmukhi":"ਮੁਖੁ ਫੀਕੋ ਕਰਿ ਸਭਨ ਦਿਖਾਵੈ। ਚਿਤ ਅਪਨੇ ਮੈ ਮੋਦ ਬਢਾਵੈ।","roman":"Mukhu pheeko kari sabhan dikhaavai | chit apne mai mod badhaavai |","meaning_en":"She showed everyone a sad face, but in her heart her joy grew:","page":1443,"meaning_status":"draft","note":"ਮੁਖੁ ਫੀਕੋ: a pale, downcast face."},{"gurmukhi":"ਸੋ ਪੁੰਨੂ ਨਿਜੁ ਸਿਰ ਤੇ ਟਾਰੋ। ਰਾਜ ਕਮੈਹੈ ਪੁਤ੍ਰ ਹਮਾਰੋ। ੨੩।","roman":"So punnoo niju sir te taaro | raaj kamaihai putr hamaaro | 23 |","meaning_en":"'I have removed that Punnu from over my head; my son will rule the kingdom.","page":1443,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1443,"meaning_status":"draft"},{"type":"verse","number":[24],"number_text":"੨੪।","page":1443,"lines":[{"gurmukhi":"ਸਵਤਿ ਸਾਲ ਤੇ ਮੈ ਜਰੀ ਨਿਜੁ ਪਤਿ ਦਯੋ ਸੰਘਾਰ।","roman":"Savti saal te mai jaree niju pati dayo sanghaar |","meaning_en":"I burned with the pain of the co-wife, and had my own husband destroyed;","page":1443,"meaning_status":"draft"},{"gurmukhi":"ਬਿਧਵਾ ਹੀ ਹ੍ਵੈ ਜੀਵਿ ਹੌ ਜੌ ਰਾਖੇ ਕਰਤਾਰ। ੨੪।","roman":"Bidhvaa hee hvai jeevi hau jau raakhe kartaar | 24 |","meaning_en":"I will live as a widow, if the Creator keeps me.","page":1443,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1443,"meaning_status":"draft"},{"type":"verse","number":[25],"number_text":"੨੫।","page":1443,"lines":[{"gurmukhi":"ਸਵਤਿ ਸਾਲ ਸਿਰ ਪੈ ਤਹਿ ਸਹਿਯੈ। ਬਿਧਵਾ ਹੀ ਹ੍ਵੈ ਕੈ ਜਗ ਰਹਿਯੈ।","roman":"Savti saal sir pai tahi sahiyai | bidhvaa hee hvai kai jag rahiyai |","meaning_en":"There the pain of a co-wife had to be borne on my head; (now) I may live in the world as a widow.","page":1443,"meaning_status":"draft","note":"Printed as 'ਸਵਤਿ ਸਾਲ ਸਿਰ ਪੈ ਤਹਿ ਸਹਿਯੈ'; the sense may be 'rather than bear a co-wife, live as a widow'. Translated as printed; uncertain."},{"gurmukhi":"ਧਨ ਕੋ ਟੋਟਿ ਕਛੂ ਮੁਹਿ ਨਾਹੀ। ਐਸੇ ਕਹੈ ਅਬਲਾ ਮਨ ਮਾਹੀ। ੨੫।","roman":"Dhan ko toti kachhoo muhi naahee | aise kahai ablaa man maahee | 25 |","meaning_en":"I have no lack of wealth' — so the woman said in her mind.","page":1443,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1443,"meaning_status":"draft"},{"type":"verse","number":[26],"number_text":"੨੬।","page":1443,"lines":[{"gurmukhi":"ਮਨ ਭਾਵਤ ਕੋ ਭੋਗ ਮੁਹਿ ਕਰਨਿ ਨ ਦੇਤੋ ਰਾਇ।","roman":"Man bhaavat ko bhog muhi karni na deto raai |","meaning_en":"'The king would not let me enjoy whomever my heart desired;","page":1443,"meaning_status":"draft"},{"gurmukhi":"ਅਬਿ ਚਿਤ ਮੈ ਜਿਹ ਚਾਹਿ ਹੋ ਲੈਹੋ ਨਿਕਟਿ ਬੁਲਾਇ। ੨੬।","roman":"Abi chit mai jih chaahi ho laiho nikti bulaai | 26 |","meaning_en":"now whomever I want in my heart, I will call close to me.'","page":1443,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1443,"meaning_status":"draft"},{"type":"verse","number":[27],"number_text":"੨੭।","page":1443,"lines":[{"gurmukhi":"ਬੈਠਿ ਝਰੋਖੇ ਮੁਜਰਾ ਲੇਵੈ। ਜਿਹ ਭਾਵੈ ਤਾ ਕੋ ਧਨੁ ਦੇਵੈ।","roman":"Baithi jharokhe mujraa levai | jih bhaavai taa ko dhanu devai |","meaning_en":"She would sit at the window receiving salutations, and give money to whomever she liked.","page":1443,"meaning_status":"draft","note":"ਮੁਜਰਾ: a salutation or presentation at court."},{"gurmukhi":"ਰਾਜ ਕਾਜ ਕਛੁ ਬਾਲ ਨ ਪਾਵੈ। ਖੇਲ ਬਿਖੈ ਦਿਨੁ ਰੈਨਿ ਗਵਾਵੈ। ੨੭।","roman":"Raaj kaaj kachhu baal na paavai | khel bikhai dinu raini gavaavai | 27 |","meaning_en":"The woman attended to no affairs of state; she wasted day and night in amusement.","page":1443,"meaning_status":"draft"}]},{"type":"verse","number":[28],"number_text":"੨੮।","page":1445,"lines":[{"gurmukhi":"ਏਕ ਦਿਵਸ ਤਿਨ ਤ੍ਰਿਯ ਯੌ ਕੀਯੋ। ਬੈਠਿ ਝਰੋਖੇ ਮੁਜਰਾ ਲੀਯੋ।","roman":"Ek divas tin triy yau keeyo | baithi jharokhe mujraa leeyo |","meaning_en":"One day that woman did this: she sat at the window and received salutations.","page":1445,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਸੂਰਨ ਕੋ ਬੋਲਿ ਪਠਾਯੋ। ਯਹ ਸੁਨਿ ਭੇਵ ਉਰਬਸੀ ਪਾਯੋ। ੨੮।","roman":"Sabh sooran ko boli pathaayo | yah suni bhev urabsee paayo | 28 |","meaning_en":"She sent for all the warriors; hearing of this, Urvashi saw her chance.","page":1445,"meaning_status":"draft","note":"ਭੇਵ ਪਾਯੋ: 'learned the secret', i.e. saw the opening."}]},{"type":"verse","number":[29],"number_text":"੨੯।","page":1445,"lines":[{"gurmukhi":"ਭੂਖਨ ਵਹੈ ਅੰਗ ਤਿਨ ਧਰੇ। ਨਿਜੁ ਆਲੈ ਤੈ ਨਿਕਸਨਿ ਕਰੇ।","roman":"Bhookhan vahai ang tin dhare | niju aalai tai nikasni kare |","meaning_en":"She put those same ornaments on her body and came out of her dwelling.","page":1445,"meaning_status":"draft"},{"gurmukhi":"ਮੁਸਕੀ ਤਾਜੀ ਚੜੀ ਬਿਰਾਜੈ। ਨਿਸ ਕੋ ਮਨੋ ਚੰਦ੍ਰਮਾ ਲਾਜੈ। ੨੯।","roman":"Muskee taajee charee biraajai | nis ko mano chandramaa laajai | 29 |","meaning_en":"She shone riding a dark Arab horse, as if putting the moon of the night to shame.","page":1445,"meaning_status":"draft","note":"ਮੁਸਕੀ: dark, black (of a horse). ਤਾਜੀ: an Arab horse."}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":1445,"meaning_status":"draft"},{"type":"verse","number":[30],"number_text":"੩੦।","page":1445,"lines":[{"gurmukhi":"ਸ੍ਯਾਮ ਛੁਟੇ ਕਚ ਕਾਂਧਨ ਊਪਰਿ ਸੋਭਿਤ ਹੈ ਅਤਿਹੀ ਘੁੰਘਰਾਰੇ।","roman":"Syaam chhute kach kaandhan oopri sobhit hai atihee ghunghraare |","meaning_en":"Her dark, very curly locks hung loose over her shoulders and looked beautiful.","page":1445,"meaning_status":"draft"},{"gurmukhi":"ਹਾਰ ਸਿੰਗਾਰ ਦਿਪੈ ਅਤਿ ਚਾਰੁ ਸੁ ਮੋ ਪਹਿ ਤੇ ਨਹਿ ਜਾਤ ਉਚਾਰੇ।","roman":"Haar singaar dipai ati chaaru su mo pahi te nahi jaat uchaare |","meaning_en":"Her necklaces and adornment shone so beautifully that I cannot describe them.","page":1445,"meaning_status":"draft"},{"gurmukhi":"ਰੀਝਤ ਦੇਵ ਅਦੇਵੇ ਸਭੈ ਸੁ ਕਹਾ ਬਪੁਰੇ ਨਰ ਦੇਵ ਬਿਚਾਰੇ।","roman":"Reejhat dev adeve sabhai su kahaa bapure nar dev bichaare |","meaning_en":"All the gods and demons were charmed; what then of poor human kings?","page":1445,"meaning_status":"draft"},{"gurmukhi":"ਬਾਲ ਕੌ ਰੋਕ ਸਭੈ ਤਜਿ ਸੋਕ ਤ੍ਰਿਲੋਕ ਕੋ ਲੋਕ ਬਿਲੋਕਿਤ ਸਾਰੇ। ੩੦।","roman":"Baal kau rok sabhai taji sok trilok ko lok bilokit saare | 30 |","meaning_en":"Stopping at the sight of the girl, all the people of the three worlds put aside their sorrow and gazed at her.","page":1445,"meaning_status":"draft","note":"ਬਾਲ ਕੌ ਰੋਕ: uncertain; read as 'stopping (to look) at the girl'."}]},{"type":"verse","number":[31],"number_text":"੩੧।","page":1445,"lines":[{"gurmukhi":"ਹਾਰ ਸਿੰਗਾਰ ਬਨਾਇ ਕੈ ਸੁੰਦਰਿ ਅੰਜਨ ਆਖਿਨ ਆਂਜਿ ਦੀਯੋ।","roman":"Haar singaar banaai kai sundri anjan aakhin aanji deeyo |","meaning_en":"Putting on necklaces and adornment, the beauty applied kohl to her eyes.","page":1445,"meaning_status":"draft"},{"gurmukhi":"ਅਤਿਹੀ ਤਨ ਬਸਤ੍ਰ ਅਨੂਪ ਧਰੇ ਜਨ ਕੰਦ੍ਰਪ ਕੋ ਬਿਨੁ ਦ੍ਰਪ ਕੀਯੋ।","roman":"Atihee tan basatr anoop dhare jan kandrap ko binu drap keeyo |","meaning_en":"She wore very matchless clothes on her body, as if she had stripped Kandarp (Kama) of his pride.","page":1445,"meaning_status":"draft","note":"ਕੰਦ੍ਰਪ: Kandarpa, Kama. ਬਿਨੁ ਦ੍ਰਪ: without pride."},{"gurmukhi":"ਕਲਗੀ ਗਜਗਾਹ ਬਨੀ ਘੁੰਘਰਾਰ ਚੜੀ ਹਯ ਕੈ ਹੁਲਸਾਤ ਹੀਯੋ।","roman":"Kalgee gajgaah banee ghunghraar charee hay kai hulsaat heeyo |","meaning_en":"With a plume, and with a gajgah on her horse, the curly-haired one rode with a joyful heart.","page":1445,"meaning_status":"draft","note":"ਗਜਗਾਹ: an ornament (plume or crest) worn on a horse's head. ਘੁੰਘਰਾਰ: curly-haired; uncertain."},{"gurmukhi":"ਬਿਨੁ ਦਾਮਨ ਹੀ ਇਹ ਕਾਮਨਿ ਯੌ ਸਭ ਭਾਮਿਨਿ ਕੋ ਮਨ ਮੋਲ ਲੀਯੋ। ੩੧।","roman":"Binu daaman hee ih kaamni yau sabh bhaamini ko man mol leeyo | 31 |","meaning_en":"In this way, without any price, this lovely woman bought the hearts of all women.","page":1445,"meaning_status":"draft"}]},{"type":"verse","number":[32],"number_text":"੩੨।","page":1445,"lines":[{"gurmukhi":"ਸੀਸ ਫਬੈ ਕਲਗੀ ਤੁਰਰੋ ਸੁਭ ਲਾਲਨ ਕੋ ਸਰਪੇਚ ਸੁਹਾਯੋ।","roman":"Sees phabai kalgee turro subh laalan ko sarpech suhaayo |","meaning_en":"A plume and a fine tassel graced her head, with a lovely ruby turban-jewel.","page":1445,"meaning_status":"draft","note":"ਤੁਰਰੋ: a turban tassel or crest."},{"gurmukhi":"ਹਾਰ ਅਪਾਰ ਧਰੇ ਉਰ ਮੈ ਮਨੁ ਦੇਖਿ ਮਨੋਜਵ ਕੋ ਬਿਰਮਾਯੋ।","roman":"Haar apaar dhare ur mai manu dekhi manojav ko birmaayo |","meaning_en":"She wore countless necklaces on her breast; seeing her, Kama's heart was beguiled.","page":1445,"meaning_status":"draft"},{"gurmukhi":"ਬੀਰੀ ਚਬਾਤ ਕਛੂ ਮੁਸਕਾਤ ਬੰਧੇ ਗਜਗਾਹ ਤੁਰੰਗ ਨਚਾਯੋ।","roman":"Beeree chabaat kachhoo muskaat bandhe gajgaah turang nachaayo |","meaning_en":"Chewing betel and smiling a little, with the gajgah fastened, she made her horse dance.","page":1445,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਯਾਮ ਭਨੈ ਮਹਿ ਲੋਕ ਕੀ ਮਾਨਹੁ ਮਾਨਨਿ ਕੋ ਮਨੁ ਮੋਹਨੁ ਆਯੋ। ੩੨।","roman":"Syaam bhanai mahi lok kee maanhu maanni ko manu mohnu aayo | 32 |","meaning_en":"Shyam says: it was as though the charmer of the hearts of proud women of the earth had come.","page":1445,"meaning_status":"draft","note":"ਸ੍ਯਾਮ: the poet's name Shyam. ਮਹਿ ਲੋਕ: the earthly world. ਮੋਹਨੁ: the charmer, also a name of Krishna; the disguised Urvashi later calls herself Mohan."}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1445,"meaning_status":"draft"},{"type":"verse","number":[33],"number_text":"੩੩।","page":1445,"lines":[{"gurmukhi":"ਪ੍ਰਭਾਵਤੀ ਰਾਨੀ ਤਬੈ ਤਾ ਕੋ ਰੂਪ ਨਿਹਾਰਿ।","roman":"Prabhaavtee raanee tabai taa ko roop nihaari |","meaning_en":"Then Queen Prabhavati, seeing her beauty,","page":1445,"meaning_status":"draft"},{"gurmukhi":"ਰੀਝਿ ਅਧਿਕ ਚਿਤ ਮੈ ਰਹੀ ਹਰ ਅਰਿ ਸਰ ਗਯੋ ਮਾਰਿ। ੩੩।","roman":"Reejhi adhik chit mai rahee har ari sar gayo maari | 33 |","meaning_en":"was greatly charmed at heart; the enemy of Har (Kama) had struck her with his arrow.","page":1445,"meaning_status":"draft","note":"ਹਰ ਅਰਿ: 'enemy of Har (Shiva)', Kama."}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"Kabitt.","page":1445,"meaning_status":"draft"},{"type":"verse","number":[34],"number_text":"੩੪।","page":1445,"lines":[{"gurmukhi":"ਕੈਧੋ ਕਾਹੂ ਰਿਖਿ ਇੰਦ੍ਰ ਆਸਨ ਤੇ ਟਾਰਿ ਦਯੋ","roman":"Kaidho kaahoo rikhi indr aasan te taari dayo","meaning_en":"'Has some sage removed Indra from his throne (and is this he)?","page":1445,"meaning_status":"draft","note":"The queen's wondering speech; no speaker heading is printed."},{"gurmukhi":"ਕੈਧੋ ਇਹ ਸੂਰਜ ਸਰੂਪ ਧਰਿ ਆਯੋ ਹੈ।","roman":"Kaidho ih sooraj saroop dhari aayo hai |","meaning_en":"Or has the Sun himself come, taking a form?","page":1445,"meaning_status":"draft"},{"gurmukhi":"ਕੈਧੋ ਚੰਦ੍ਰ ਚੰਦ੍ਰਲੋਕ ਛੋਰਿ ਕੈ ਸਿਪਾਹੀ ਬਨ","roman":"Kaidho chandr chandralok chhori kai sipaahee ban","meaning_en":"Or has the Moon left the world of the moon and, becoming a soldier,","page":1445,"meaning_status":"draft"},{"gurmukhi":"ਮੇਰੇ ਜਾਨ ਤੀਰਥ ਅਨ੍ਹੈਬੈ ਕੋ ਸਿਧਾਯੋ ਹੈ।","roman":"Mere jaan teerath anhaibai ko sidhaayo hai |","meaning_en":"set out, as I think, to bathe at the places of pilgrimage?","page":1445,"meaning_status":"draft"},{"gurmukhi":"ਕੈਧੋ ਹੈ ਅਨੰਗ ਅਰੁਧੰਗਕ ਕੇ ਅੰਤਕ ਤੇ","roman":"Kaidho hai anang arudhangak ke antak te","meaning_en":"Or is it Anang (Kama) who, fearing the destroyer, the half-bodied one (Shiva),","page":1445,"meaning_status":"draft","note":"ਅਰੁਧੰਗਕ ਕੇ ਅੰਤਕ: read as 'the destroyer who is half-bodied' (Shiva as Ardhanarishvar), who burnt Kama; uncertain."},{"gurmukhi":"ਮਾਨੁਖ ਕੋ ਰੂਪ ਕੈ ਕੈ ਆਪੁ ਕੌ ਛਪਾਯੋ ਹੈ।","roman":"Maanukh ko roop kai kai aapu kau chhapaayo hai |","meaning_en":"has taken a human form and hidden himself?","page":1445,"meaning_status":"draft"},{"gurmukhi":"ਕੈਧੋ ਯਹ ਸਸਿਯਾ ਕੇ ਰਸਿਯਾ ਨੈ ਕੋਪ ਕੈ ਕੈ","roman":"Kaidho yah sasiyaa ke rasiyaa nai kop kai kai","meaning_en":"Or has Sassi's lover, in his anger,","page":1445,"meaning_status":"draft","note":"ਸਸਿਯਾ ਕੇ ਰਸਿਯਾ: Sassi's lover, Punnu."},{"gurmukhi":"ਮੋਰੇ ਛਲਬੇ ਕੌ ਕਛੂ ਛਲ ਸੋ ਬਨਾਯੋ ਹੈ। ੩੪।","roman":"More chhalbe kau kachhoo chhal so banaayo hai | 34 |","meaning_en":"devised some trick to deceive me?'","page":1445,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1447,"meaning_status":"draft"},{"type":"verse","number":[35],"number_text":"੩੫।","page":1447,"lines":[{"gurmukhi":"ਜਬ ਲੌ ਬੈਨ ਕਹਨ ਨਹਿ ਪਾਈ। ਤਬ ਲੌ ਨਿਕਟ ਗਯੋ ਵਹੁ ਆਈ।","roman":"Jab lau bain kahan nahi paaee | tab lau nikat gayo vahu aaee |","meaning_en":"Before she could say a word, the rider came close to her.","page":1447,"meaning_status":"draft","note":"ਗਯੋ ... ਆਈ: the verbs mix masculine and feminine, as the rider is Urvashi in a man's guise."},{"gurmukhi":"ਰੂਪ ਨਿਹਾਰਿ ਮਤ ਹ੍ਵੈ ਝੂਲੀ। ਗ੍ਰਿਹ ਕੀ ਸਕਲ ਤਾਹਿ ਸੁਧਿ ਭੂਲੀ। ੩੫।","roman":"Roop nihaari mat hvai jhoolee | grih kee sakal taahi sudhi bhoolee | 35 |","meaning_en":"Seeing that beauty she swayed as if drunk, and forgot all thought of her home.","page":1447,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸੋਰਠਾ","gurmukhi":"ਸੋਰਠਾ","roman":"Sorthaa","meaning_en":"Sortha.","page":1447,"meaning_status":"draft"},{"type":"verse","number":[36],"number_text":"੩੬।","page":1447,"lines":[{"gurmukhi":"ਪਠਏ ਦੂਤ ਅਨੇਕ ਅਮਿਤ ਦਰਬੁ ਤਿਨ ਕੌ ਦਯੋ।","roman":"Pathae doot anek amit darbu tin kau dayo |","meaning_en":"She sent many messengers and gave them boundless wealth;","page":1447,"meaning_status":"draft"},{"gurmukhi":"ਕਹਿਯੋ ਮਹੂਰਤ ਏਕ ਕ੍ਰਿਪਾ ਕਰੋ ਇਹ ਗ੍ਰਿਹ ਬਸੋ। ੩੬।","roman":"Kahiyo mahoorat ek kripaa karo ih grih baso | 36 |","meaning_en":"she said, 'Be kind and stay in this house for one muhurat.'","page":1447,"meaning_status":"draft","note":"ਮਹੂਰਤ: a short period of time (about 48 minutes)."}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"Kabitt.","page":1447,"meaning_status":"draft"},{"type":"verse","number":[37],"number_text":"੩੭।","page":1447,"lines":[{"gurmukhi":"ਕੈਧੌ ਅਲਿਕੇਸ ਹੋ ਕਿ ਸਸਿ ਹੋ ਦਿਨੇਸ ਹੋ","roman":"Kaidhau alikes ho ki sasi ho dines ho","meaning_en":"'Are you Alkesh (Kuber), or the moon, or the sun?","page":1447,"meaning_status":"draft","note":"ਅਲਿਕੇਸ: lord of Alaka, Kuber, god of wealth."},{"gurmukhi":"ਕਿ ਰੂਪ ਹੂੰ ਕਿ ਭੇਸ ਹੋ ਜਹਾਨ ਮੈ ਸੁਹਾਏ ਹੋ।","roman":"Ki roop hoon ki bhes ho jahaan mai suhaae ho |","meaning_en":"Or are you Beauty itself in disguise, gracing the world?","page":1447,"meaning_status":"draft"},{"gurmukhi":"ਸੇਸ ਹੋ ਸੁਰੇਸ ਹੋ ਗਨੇਸ ਹੋ ਮਹੇਸ ਹੋ ਜੀ","roman":"Ses ho sures ho ganes ho mahes ho jee","meaning_en":"Are you Shesh, Suresh (Indra), Ganesh or Mahesh (Shiva)?","page":1447,"meaning_status":"draft"},{"gurmukhi":"ਕੈਧੌ ਜਗਤੇਸ ਤੁਮ ਬੇਦਨ ਬਤਾਏ ਹੋ।","roman":"Kaidhau jagtes tum bedan bataae ho |","meaning_en":"Or are you the Lord of the world of whom the Vedas tell?","page":1447,"meaning_status":"draft"},{"gurmukhi":"ਕਾਲਿੰਦ੍ਰੀ ਕੇ ਏਸ ਹੋ ਕਿ ਤੁਮ ਹੀ ਜਲੇਸ ਹੋ","roman":"Kaalindree ke es ho ki tum hee jales ho","meaning_en":"Are you the lord of the Kalindri (Yamuna), or are you Jalesh (lord of the waters)?","page":1447,"meaning_status":"draft","note":"ਕਾਲਿੰਦ੍ਰੀ ਕੇ ਏਸ: lord of the Yamuna, i.e. Krishna. ਜਲੇਸ: Varun, lord of the waters."},{"gurmukhi":"ਬਤਾਵੌ ਕੌਨ ਦੇਸ ਕੇ ਨਰੇਸੁਰ ਕੇ ਜਾਏ ਹੋ।","roman":"Bataavau kaun des ke naresur ke jaae ho |","meaning_en":"Tell me, of the king of which country you are born?","page":1447,"meaning_status":"draft"},{"gurmukhi":"ਕਹੋ ਮੇਰੇ ਏਸ ਕਿਹ ਕਾਜ ਨਿਜੁ ਦੇਸ ਛੋਰਿ","roman":"Kaho mere es kih kaaj niju des chhori","meaning_en":"Tell me, my lord, for what purpose have you left your own country","page":1447,"meaning_status":"draft"},{"gurmukhi":"ਚਾਕਰੀ ਕੋ ਭੇਸ ਕੈ ਹਮਾਰੇ ਦੇਸ ਆਏ ਹੋ। ੩੭।","roman":"Chaakree ko bhes kai hamaare des aae ho | 37 |","meaning_en":"and come to our country in the guise of one seeking service?'","page":1447,"meaning_status":"draft","note":"ਚਾਕਰੀ ਕੋ ਭੇਸ: the dress of one in service, a soldier."}]},{"type":"verse","number":[38],"number_text":"੩੮।","page":1447,"lines":[{"gurmukhi":"ਹੌ ਨ ਅਲਿਕੇਸ ਹੌ ਨ ਸਸਿ ਹੌ ਦਿਨੇਸ ਹੌ","roman":"Hau na alikes hau na sasi hau dines hau","meaning_en":"'I am not Alkesh, nor the moon, nor the sun,","page":1447,"meaning_status":"draft","note":"Urvashi's reply, in her guise as a prince."},{"gurmukhi":"ਨ ਰੂਪ ਹੂ ਕੇ ਭੇਸ ਕੈ ਜਹਾਨ ਮੈ ਸੁਹਾਯੋ ਹੌ।","roman":"Na roop hoo ke bhes kai jahaan mai suhaayo hau |","meaning_en":"nor Beauty in disguise gracing the world.","page":1447,"meaning_status":"draft"},{"gurmukhi":"ਸੇਸ ਨ ਸੁਰੇਸ ਹੌ ਗਨੇਸ ਹੌ ਮਹੇਸ ਨਹੀ ਹੌ","roman":"Ses na sures hau ganes hau mahes nahee hau","meaning_en":"I am not Shesh nor Suresh, I am not Ganesh nor Mahesh,","page":1447,"meaning_status":"draft","note":"ਗਨੇਸ ਹੌ: printed without a 'not'; the line's sense is negative throughout."},{"gurmukhi":"ਨ ਜਗਤੇਸ ਹੌ ਜੁ ਬੇਦਨ ਬਤਾਯੋ ਹੌ।","roman":"Na jagtes hau ju bedan bataayo hau |","meaning_en":"nor am I the Lord of the world of whom the Vedas tell.","page":1447,"meaning_status":"draft"},{"gurmukhi":"ਕਾਲਿੰਦ੍ਰੀ ਕੇ ਏਸ ਅਥਿਤੇਸ ਮੈ ਜਲੇਸ ਨਹੀ","roman":"Kaalindree ke es athites mai jales nahee","meaning_en":"I am not the lord of the Kalindri, nor the lord of guests, nor Jalesh;","page":1447,"meaning_status":"draft","note":"ਅਥਿਤੇਸ: uncertain; read as 'lord of guests' (atithi-esh)."},{"gurmukhi":"ਦਛਿਨ ਕੇ ਦੇਸ ਕੇ ਨਰੇਸੁਰ ਕੋ ਜਾਯੋ ਹੌ।","roman":"Dachhin ke des ke naresur ko jaayo hau |","meaning_en":"I am born of the king of a southern country.","page":1447,"meaning_status":"draft","note":"ਦਛਿਨ: the south."},{"gurmukhi":"ਮੋਹਨ ਹੈ ਨਾਮ ਆਗੇ ਜੈਹੋ ਸਸੁਰਾਰੇ ਧਾਮ","roman":"Mohan hai naam aage jaiho sasuraare dhaam","meaning_en":"My name is Mohan; I am going on to my in-laws' house;","page":1447,"meaning_status":"draft"},{"gurmukhi":"ਸੋਭਾ ਸੁਨਿ ਤੁਮਰੀ ਤਮਾਸੇ ਕਾਜ ਆਯੋ ਹੌ। ੩੮।","roman":"Sobhaa suni tumree tamaase kaaj aayo hau | 38 |","meaning_en":"hearing of your splendour, I have come to see the sight.'","page":1447,"meaning_status":"draft","note":"ਤਮਾਸੇ ਕਾਜ: Persian tamasha, 'to see the spectacle'."}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":1447,"meaning_status":"draft"},{"type":"verse","number":[39],"number_text":"੩੯।","page":1447,"lines":[{"gurmukhi":"ਤੇਰੀ ਸੋਭਾ ਸੁਨਿ ਕੈ ਸੁਨਿ ਸੁੰਦਰਿ ਆਯੋ ਈਹਾ ਚਲਿ ਕੋਸ ਹਜਾਰੌ।","roman":"Teree sobhaa suni kai suni sundri aayo eehaa chali kos hajaarau |","meaning_en":"'Hearing of your splendour, O beauty, I have come here, travelling thousands of kos.","page":1447,"meaning_status":"draft"},{"gurmukhi":"ਆਜੁ ਮਹੂਰਤ ਹੈ ਤਿਤ ਕੋ ਕਛੁ ਸਾਥ ਮਿਲੈ ਨਹੀ ਤ੍ਰਾਸ ਬਿਚਾਰੌ।","roman":"Aaju mahoorat hai tit ko kachhu saath milai nahee traas bichaarau |","meaning_en":"Today is the auspicious hour for (going) there; I fear I may not catch up with my party.","page":1447,"meaning_status":"draft","note":"ਕਛੁ ਸਾਥ ਮਿਲੈ ਨਹੀ ਤ੍ਰਾਸ ਬਿਚਾਰੌ: uncertain."},{"gurmukhi":"ਰੀਤ ਹੈ ਧਾਮ ਇਹੈ ਹਮਰੇ ਨਿਜੁ ਨਾਰਿ ਬਿਨਾ ਨਹੀ ਔਰ ਨਿਹਾਰੌ।","roman":"Reet hai dhaam ihai hamre niju naari binaa nahee aur nihaarau |","meaning_en":"This is the custom in our house: apart from one's own wife, one looks at no other.","page":1447,"meaning_status":"draft"},{"gurmukhi":"ਖੇਲੋ ਹਸੌ ਸੁਖ ਸੋ ਤੁਮ ਹੂੰ ਮੁਹਿ ਦੇਹੁ ਬਿਦਾ ਸਸੁਰਾਰਿ ਸਿਧਾਰੌ। ੩੯।","roman":"Khelo hasau sukh so tum hoon muhi dehu bidaa sasuraari sidhaarau | 39 |","meaning_en":"You play and laugh in happiness; give me leave, that I may go to my in-laws'.'","page":1447,"meaning_status":"draft"}]},{"type":"verse","number":[40],"number_text":"੪੦।","page":1447,"lines":[{"gurmukhi":"ਬਾਤ ਬਿਦਾ ਕੀ ਸੁਨੀ ਜਬ ਹੀ ਬਿਨੁ ਚੈਨ ਭਈ ਨ ਸੁਹਾਵਤ ਜੀ ਕੀ।","roman":"Baat bidaa kee sunee jab hee binu chain bhaee na suhaavat jee kee |","meaning_en":"As soon as she heard talk of leaving, she grew restless; nothing pleased her heart.","page":1447,"meaning_status":"draft"},{"gurmukhi":"ਲਾਲ ਗੁਲਾਲ ਸੀ ਬਾਲ ਹੁਤੀ ਤਤਕਾਲ ਭਈ ਮੁਖ ਕੀ ਛਬਿ ਫੀਕੀ।","roman":"Laal gulaal see baal hutee tatkaal bhaee mukh kee chhabi pheekee |","meaning_en":"The woman who had been red as gulal at once lost the colour from her face.","page":1447,"meaning_status":"draft","note":"ਗੁਲਾਲ: red powder."},{"gurmukhi":"ਹਾਥ ਉਚਾਇ ਹਨੀ ਛਤਿਯਾ ਉਰ ਪੈ ਲਸੈ ਸੌ ਮੁੰਦਰੀ ਅੰਗੁਰੀ ਕੀ।","roman":"Haath uchaai hanee chhatiyaa ur pai lasai sau mundree anguree kee |","meaning_en":"Raising her hand she beat her breast, and the ring of her finger left its mark on her bosom;","page":1447,"meaning_status":"draft","note":"ਲਸੈ ਸੌ ਮੁੰਦਰੀ: read as 'the ring (mark) shone'; uncertain."},{"gurmukhi":"ਦੇਖਨ ਕੋ ਪਿਯ ਕੌ ਤਿਯ ਕੀ ਪ੍ਰਗਟੀ ਅਖਿਯਾ ਜੁਗ ਜਾਨੁਕ ਹੀ ਕੀ। ੪੦।","roman":"Dekhan ko piy kau tiy kee pragtee akhiyaa jug jaanuk hee kee | 40 |","meaning_en":"it was as if the two eyes of the woman's heart had appeared, to look upon her beloved.","page":1447,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1449,"meaning_status":"draft"},{"type":"verse","number":[41],"number_text":"੪੧।","page":1449,"lines":[{"gurmukhi":"ਮਨੁ ਤਰਫਤ ਤਵ ਮਿਲਨ ਕੋ ਤਨੁ ਭੇਟਤ ਨਹਿ ਜਾਇ।","roman":"Manu tarphat tav milan ko tanu bhetat nahi jaai |","meaning_en":"'My heart writhes to meet you, yet my body cannot come to your embrace;","page":1449,"meaning_status":"draft","note":"The queen speaks; no speaker heading is printed."},{"gurmukhi":"ਜੀਭ ਜਰੋ ਤਿਨ ਨਾਰਿ ਕੀ ਦੈ ਤੁਹਿ ਬਿਦਾ ਬੁਲਾਇ। ੪੧।","roman":"Jeebh jaro tin naari kee dai tuhi bidaa bulaai | 41 |","meaning_en":"may the tongue burn of the woman who calls you and bids you farewell.'","page":1449,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"Kabitt.","page":1449,"meaning_status":"draft"},{"type":"verse","number":[42],"number_text":"੪੨।","page":1449,"lines":[{"gurmukhi":"ਕੋਊ ਦਿਨ ਰਹੋ ਹਸਿ ਬੋਲੋ ਆਛੀ ਬਾਤੈ","roman":"Ko'oo din raho hasi bolo aachhee baatai","meaning_en":"'Stay for some days; laugh and speak pleasant words;","page":1449,"meaning_status":"draft","note":"The queen continues."},{"gurmukhi":"ਕਹੋ ਕਹਾ ਸਸੁਰਾਰਿ ਕੀ ਅਨੋਖੀ ਪ੍ਰੀਤਿ ਪਾਗੀ ਹੈ।","roman":"Kaho kahaa sasuraari kee anokhee preeti paagee hai |","meaning_en":"tell me, what strange love of your in-laws' house are you so steeped in?","page":1449,"meaning_status":"draft"},{"gurmukhi":"ਯਹੈ ਰਾਜ ਲੀਜੈ ਯਾ ਕੋ ਰਾਜਾ ਹ੍ਵੈਕੈ ਰਾਜ ਕੀਜੈ","roman":"Yahai raaj leejai yaa ko raajaa hvaikai raaj keejai","meaning_en":"Take this kingdom; become its king and rule it;","page":1449,"meaning_status":"draft"},{"gurmukhi":"ਹਾਥੁ ਚਾਇ ਦੀਜੈ ਮੋਹਿ ਯਹੈ ਜਿਯ ਜਾਗੀ ਹੈ।","roman":"Haathu chaai deejai mohi yahai jiy jaagee hai |","meaning_en":"give to me by your own raised hand; this is the wish that has woken in my heart.","page":1449,"meaning_status":"draft","note":"ਹਾਥੁ ਚਾਇ ਦੀਜੈ ਮੋਹਿ: read as 'lift your hand and give to me' (as in the next verse, a morsel from his hand); uncertain."},{"gurmukhi":"ਤੁਮ ਕੋ ਨਿਹਾਰਿ ਕਿਯ ਮਾਰ ਨੈ ਸੁ ਮਾਰ ਮੋ ਕੌ","roman":"Tum ko nihaari kiy maar nai su maar mo kau","meaning_en":"Seeing you, Mar (Kama) has struck me a blow,","page":1449,"meaning_status":"draft","note":"ਮਾਰ: a name of Kama, with a play on ਮਾਰ 'a blow'."},{"gurmukhi":"ਤਾ ਤੇ ਬਿਸੰਭਾਰ ਭਈ ਨੀਂਦ ਭੂਖਿ ਭਾਗੀ ਹੈ।","roman":"Taa te bisanbhaar bhaee neend bhookhi bhaagee hai |","meaning_en":"so I have lost my senses, and sleep and hunger have fled.","page":1449,"meaning_status":"draft"},{"gurmukhi":"ਤਹਾ ਕੌ ਨ ਜੈਯੇ ਮੇਰੀ ਸੇਜ ਕੋ ਸੁਹੈਯੈ ਆਨਿ","roman":"Tahaa kau na jaiye meree sej ko suhaiyai aani","meaning_en":"Do not go there; come and grace my bed;","page":1449,"meaning_status":"draft"},{"gurmukhi":"ਲਗਨ ਨਿਗੌਡੀ ਨਾਥ ਤੇਰੇ ਸਾਥ ਲਾਗੀ ਹੈ। ੪੨।","roman":"Lagan nigaudee naath tere saath laagee hai | 42 |","meaning_en":"this wretched attachment, my lord, has fastened upon you.'","page":1449,"meaning_status":"draft","note":"ਨਿਗੌਡੀ: 'wretched', a term of mild abuse."}]},{"type":"verse","number":[43],"number_text":"੪੩।","page":1449,"lines":[{"gurmukhi":"ਏਕ ਪਾਇ ਸੇਵਾ ਕਰੌ ਚੇਰੀ ਹ੍ਵੈ ਕੈ ਨੀਰ ਭਰੌ","roman":"Ek paai sevaa karau cheree hvai kai neer bharau","meaning_en":"'I will serve you standing on one foot; as a slave-girl I will draw water;","page":1449,"meaning_status":"draft"},{"gurmukhi":"ਤੁਹੀ ਕੌ ਬਰੌ ਮੋਰੀ ਇਛਾ ਪੂਰੀ ਕੀਜਿਯੈ।","roman":"Tuhee kau barau moree ichhaa pooree keejiyai |","meaning_en":"I will wed you alone; fulfil my desire.","page":1449,"meaning_status":"draft"},{"gurmukhi":"ਯਹੈ ਰਾਜ ਲੇਹੁ ਹਾਥ ਉਠਾਇ ਮੋ ਕੌ ਟੂਕਾ ਦੇਹੁ","roman":"Yahai raaj lehu haath uthaai mo kau tookaa dehu","meaning_en":"Take this kingdom, and with your own raised hand give me a morsel;","page":1449,"meaning_status":"draft","note":"ਟੂਕਾ: a piece of bread."},{"gurmukhi":"ਹਮ ਸੌ ਬਢਾਵ ਨੇਹੁ ਜਾ ਤੇ ਲਾਲ ਜੀਜਿਯੈ।","roman":"Ham sau badhaav nehu jaa te laal jeejiyai |","meaning_en":"increase your love for me, dear one, that I may live.","page":1449,"meaning_status":"draft"},{"gurmukhi":"ਜੌ ਕਹੌ ਬਿਕੈਹੌ ਜਹਾ ਭਾਖੋ ਤਹਾ ਚਲੀ ਜੈਹੌ","roman":"Jau kahau bikaihau jahaa bhaakho tahaa chalee jaihau","meaning_en":"If you say so, I will be sold; wherever you say, there I will go;","page":1449,"meaning_status":"draft"},{"gurmukhi":"ਐਸੋ ਹਾਲ ਹੇਰਿ ਨਾਥ ਕਬਹੂੰ ਪ੍ਰਸੀਜਿਯੈ।","roman":"Aiso haal heri naath kabhoon praseejiyai |","meaning_en":"seeing such a state, my lord, relent at last.","page":1449,"meaning_status":"draft"},{"gurmukhi":"ਯਾਹੀ ਠੌਰ ਰਹੋ ਹਸਿ ਬੋਲੋ ਆਛੀ ਬਾਤੈ ਕਹੋ","roman":"Yaahee thaur raho hasi bolo aachhee baatai kaho","meaning_en":"Stay in this very place, laugh and speak pleasant words,","page":1449,"meaning_status":"draft"},{"gurmukhi":"ਜਾਨ ਸਸੁਰਾਰਿ ਕੋ ਨ ਨਾਮੁ ਫੇਰ ਲੀਜਿਯੈ। ੪੩।","roman":"Jaan sasuraari ko na naamu pher leejiyai | 43 |","meaning_en":"and do not again speak of going to your in-laws'.'","page":1449,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":1449,"meaning_status":"draft"},{"type":"verse","number":[44],"number_text":"੪੪।","page":1449,"lines":[{"gurmukhi":"ਕ੍ਯੋ ਨਿਜੁ ਤ੍ਰਿਯ ਤਜਿ ਕੇ ਸੁਨਿ ਸੁੰਦਰਿ ਤੋਹਿ ਭਜੇ ਧ੍ਰਮ ਜਾਤ ਹਮਾਰੋ।","roman":"Kyo niju triy taji ke suni sundri tohi bhaje dhram jaat hamaaro |","meaning_en":"'Listen, O beauty: why should I leave my own wife and lie with you? My dharma would be lost.","page":1449,"meaning_status":"draft","note":"Mohan (Urvashi in disguise) replies; no speaker heading is printed."},{"gurmukhi":"ਰਾਜ ਕਰੌ ਅਪਨੇ ਤੁਮਹੀ ਸੁਖ ਸੋ ਇਨ ਧਾਮਨ ਬੀਚ ਬਿਹਾਰੋ।","roman":"Raaj karau apne tumhee sukh so in dhaaman beech bihaaro |","meaning_en":"Rule your kingdom yourself, and take your pleasure in happiness in these palaces.","page":1449,"meaning_status":"draft"},{"gurmukhi":"ਮੈ ਪ੍ਰਗਟਿਯੋ ਜਬ ਤੇ ਤਬ ਤੇ ਤਜਿ ਕਾਨਿ ਤ੍ਰਿਯਾ ਨਹਿ ਆਨ ਨਿਹਾਰੋ।","roman":"Mai pragtiyo jab te tab te taji kaani triyaa nahi aan nihaaro |","meaning_en":"Ever since I was born, I have never cast off propriety and looked at another woman.","page":1449,"meaning_status":"draft"},{"gurmukhi":"ਕ੍ਯਾ ਤੁਮ ਖ੍ਯਾਲ ਪਰੋ ਹਮਰੇ ਮਨ ਧੀਰ ਧਰੋ ਰਘੂਨਾਥ ਉਚਾਰੋ। ੪੪।","roman":"Kyaa tum khyaal paro hamre man dheer dharo raghoonaath uchaaro | 44 |","meaning_en":"Why have you set your thoughts on me? Steady your mind and utter the name of Raghunath (Ram).'","page":1449,"meaning_status":"draft"}]},{"type":"verse","number":[45],"number_text":"੪੫।","page":1449,"lines":[{"gurmukhi":"ਕ੍ਰੋਰਿ ਉਪਾਇ ਕਰੋ ਲਲਨਾ ਤੁਮ ਕੇਲ ਕਰੇ ਬਿਨੁ ਮੈ ਨ ਟਰੋਂਗੀ।","roman":"Krori upaai karo lalnaa tum kel kare binu mai na tarongee |","meaning_en":"'Though you try a million means, dear one, I will not give way without making love with you.","page":1449,"meaning_status":"draft","note":"The queen replies."},{"gurmukhi":"ਭਾਜਿ ਰਹੋਬ ਕਹਾ ਹਮ ਤੇ ਤੁਮ ਭਾਤਿ ਭਲੀ ਤੁਹਿ ਆਜ ਬਰੋਂਗੀ।","roman":"Bhaaji rahob kahaa ham te tum bhaati bhalee tuhi aaj barongee |","meaning_en":"Where will you run to escape me? Today I will wed you in fine fashion.","page":1449,"meaning_status":"draft","note":"ਰਹੋਬ: printed so; read as 'will you stay / get away'."},{"gurmukhi":"ਜੌ ਨ ਮਿਲੋ ਤੁਮ ਆਜੁ ਹਮੈ ਅਬਹੀ ਤਬ ਮੈ ਬਿਖ ਖਾਇ ਮਰੋਂਗੀ।","roman":"Jau na milo tum aaju hamai abhee tab mai bikh khaai marongee |","meaning_en":"If you do not unite with me today, this very moment, I will eat poison and die.","page":1449,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰੀਤਮ ਕੇ ਦਰਸੇ ਪਰਸੇ ਬਿਨੁ ਪਾਵਕ ਮੈਨ ਪ੍ਰਵੇਸ ਕਰੋਂਗੀ। ੪੫।","roman":"Preetam ke darse parse binu paavak main praves karongee | 45 |","meaning_en":"Without seeing and touching my beloved, I will enter the fire of Main (Kama).'","page":1449,"meaning_status":"draft","note":"ਪਾਵਕ ਮੈਨ: read as 'the fire of Kama (love)'; if divided ਮੈ ਨ it would say 'I will not enter the fire', which does not suit the threat; uncertain."}]},{"type":"heading","kind":"speaker","name":"ਮੋਹਨ ਬਾਚ","gurmukhi":"ਮੋਹਨ ਬਾਚ","roman":"Mohan baach","meaning_en":"Mohan said:","page":1449,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1449,"meaning_status":"draft"},{"type":"verse","number":[46],"number_text":"੪੬।","page":1449,"lines":[{"gurmukhi":"ਰੀਤਿ ਯਹੈ ਕੁਲ ਪਰੀ ਹਮਾਰੇ। ਸੁ ਮੈ ਕਹਤ ਹੋ ਤੀਰ ਤਿਹਾਰੇ।","roman":"Reeti yahai kul paree hamaare | su mai kahat ho teer tihaare |","meaning_en":"'This custom has come down in our family, and I tell it to you:","page":1449,"meaning_status":"draft"},{"gurmukhi":"ਚਲ ਕਿਸਹੁੰ ਕੇ ਧਾਮ ਨ ਜਾਹੀ। ਚਲਿ ਆਵੈ ਛੋਰੈ ਤਿਹ ਨਾਹੀ। ੪੬।","roman":"Chal kishun ke dhaam na jaahee | chali aavai chhorai tih naahee | 46 |","meaning_en":"we do not go to anyone's house; but one who comes to us, we do not turn away.'","page":1449,"meaning_status":"draft"}]},{"type":"verse","number":[47],"number_text":"੪੭।","page":1449,"lines":[{"gurmukhi":"ਜਬ ਯਹ ਬਾਤ ਤ੍ਰਿਯਹਿ ਸੁਨਿ ਪਾਈ। ਨਿਜੁ ਮਤਿ ਬੀਚ ਯਹੈ ਠਹਰਾਈ।","roman":"Jab yah baat triyhi suni paaee | niju mati beech yahai thahraaee |","meaning_en":"When the woman heard this, she settled it in her mind:","page":1449,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਚਲਿ ਧਾਮ ਮੀਤ ਕੇ ਜੈਹੋ। ਮਨ ਭਾਵਤ ਕੇ ਭੋਗ ਕਮੈਹੋ। ੪੭।","roman":"Ho chali dhaam meet ke jaiho | man bhaavat ke bhog kamaiho | 47 |","meaning_en":"'I will go to my lover's house and enjoy the pleasures my heart desires.'","page":1449,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":1451,"meaning_status":"draft"},{"type":"verse","number":[48],"number_text":"੪੮।","page":1451,"lines":[{"gurmukhi":"ਆਜੁ ਪਯਾਨ ਕਰੋਗੀ ਤਹਾ ਸਖੀ ਭੂਖਨ ਬਸਤ੍ਰ ਅਨੂਪ ਬਨਾਊ।","roman":"Aaju payaan karogee tahaa sakhee bhookhan basatr anoop banaaoo |","meaning_en":"'Today I will set out for that place, friend; I will put on matchless ornaments and clothes.","page":1451,"meaning_status":"draft","note":"The queen speaks to her companion."},{"gurmukhi":"ਮੀਤ ਕੇ ਧਾਮ ਬਦ੍ਯੋ ਮਿਲਿਬੋ ਨਿਸ ਹੋਤ ਨਹੀ ਅਬ ਹੀ ਮਿਲ ਆਊ।","roman":"Meet ke dhaam badyo milibo nis hot nahee ab hee mil aaoo |","meaning_en":"The meeting is fixed at my lover's house; night will not come soon enough, so let me go and meet him now.","page":1451,"meaning_status":"draft","note":"ਨਿਸ ਹੋਤ ਨਹੀ: 'night is not coming'; sense uncertain."},{"gurmukhi":"ਸਾਵਨ ਮੋ ਮਨ ਭਾਵਨ ਕੇ ਲੀਏ ਸਾਤ ਸਮੁੰਦ੍ਰਨ ਕੇ ਤਰਿ ਜਾਊ।","roman":"Saavan mo man bhaavan ke lee'e saat samundran ke tari jaaoo |","meaning_en":"For my heart's beloved I would swim across the seven seas, even in Sawan.","page":1451,"meaning_status":"draft","note":"ਸਾਵਨ ਮੋ: read as 'in the month of Sawan' (the rains); uncertain."},{"gurmukhi":"ਕ੍ਰੋਰਿ ਉਪਾਉ ਕਰੌ ਸਜਨੀ ਪਿਯ ਕੋ ਤਨ ਕੈ ਤਨ ਭੇਟਨ ਪਾਊ। ੪੮।","roman":"Krori upaau karau sajnee piy ko tan kai tan bhetan paaoo | 48 |","meaning_en":"I would try a million means, friend, to touch my beloved's body with my own.'","page":1451,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1451,"meaning_status":"draft"},{"type":"verse","number":[49],"number_text":"੪੯।","page":1451,"lines":[{"gurmukhi":"ਜਬ ਤੇ ਮੈ ਭਵ ਮੋ ਭਵ ਲੀਯੋ। ਆਨਿ ਤ੍ਰਿਯਾ ਸੌ ਭੋਗ ਨ ਕੀਯੋ।","roman":"Jab te mai bhav mo bhav leeyo | aani triyaa sau bhog na keeyo |","meaning_en":"'Since I took birth in the world, I have not lain with another woman.","page":1451,"meaning_status":"draft","note":"Mohan speaks again; no speaker heading is printed."},{"gurmukhi":"ਜੌ ਐਸੋ ਚਿਤ ਰਿਝਿਯੋ ਤਿਹਾਰੋ। ਤੌ ਕਹਾ ਬਸਿ ਚਲਤ ਹਮਾਰੋ। ੪੯।","roman":"Jau aiso chit rijhiyo tihaaro | tau kahaa basi chalat hamaaro | 49 |","meaning_en":"But if your heart is so enamoured, what power have I against it?","page":1451,"meaning_status":"draft"}]},{"type":"verse","number":[50],"number_text":"੫੦।","page":1451,"lines":[{"gurmukhi":"ਨ ਪਿਯਾਨ ਧਾਮ ਤਵ ਕਰੋ। ਨਰਕ ਪਰਨ ਤੇ ਅਤਿ ਚਿਤ ਡਰੋ।","roman":"Na piyaan dhaam tav karo | narak paran te ati chit daro |","meaning_en":"I will not go to your house; I greatly fear falling into hell.","page":1451,"meaning_status":"draft"},{"gurmukhi":"ਤੁਮਹੀ ਧਾਮ ਹਮਾਰੇ ਐਯਹੁ। ਮਨ ਭਾਵਤ ਕੋ ਭੋਗ ਕਮੈਯਹੁ। ੫੦।","roman":"Tumhee dhaam hamaare aiyhu | man bhaavat ko bhog kamaiyhu | 50 |","meaning_en":"Come to my house yourself, and enjoy the pleasures your heart desires.'","page":1451,"meaning_status":"draft"}]},{"type":"verse","number":[51],"number_text":"੫੧।","page":1451,"lines":[{"gurmukhi":"ਬਾਤੇ ਕਰਤ ਨਿਸਾ ਪਰਿ ਗਈ। ਤ੍ਰਿਯ ਕੌ ਕਾਮ ਕਰਾ ਅਤਿ ਭਈ।","roman":"Baate karat nisaa pari gaee | triy kau kaam karaa ati bhaee |","meaning_en":"As they talked, night fell, and the woman's passion grew strong.","page":1451,"meaning_status":"draft","note":"ਕਾਮ ਕਰਾ: read as kam-kala, 'the power of desire'; uncertain."},{"gurmukhi":"ਅਧਿਕ ਅਨੂਪਮ ਭੇਸ ਬਨਾਯੋ। ਤਾ ਕੌ ਤਿਹ ਗ੍ਰਿਹ ਓਰ ਪਠਾਯੋ। ੫੧।","roman":"Adhik anoopam bhes banaayo | taa kau tih grih or pathaayo | 51 |","meaning_en":"She put on a most matchless dress, and sent him on towards his house.","page":1451,"meaning_status":"draft","note":"The subject of the first half is taken as the queen; it could also be Mohan."}]},{"type":"verse","number":[52],"number_text":"੫੨।","page":1451,"lines":[{"gurmukhi":"ਤਬ ਮੋਹਨ ਨਿਜੁ ਗ੍ਰਿਹ ਚਲਿ ਆਯੋ। ਅਧਿਕ ਅਨੂਪਮ ਭੇਸ ਬਨਾਯੋ।","roman":"Tab mohan niju grih chali aayo | adhik anoopam bhes banaayo |","meaning_en":"Then Mohan came to his own house and put on a most matchless dress.","page":1451,"meaning_status":"draft"},{"gurmukhi":"ਟਕਿਯਨ ਕੀ ਚਪਟੀ ਉਰਬਸੀ। ਮੋਮ ਮਾਰਿ ਆਸਨ ਸੌ ਕਸੀ। ੫੨।","roman":"Takiyan kee chaptee urabsee | mom maari aasan sau kasee | 52 |","meaning_en":"Urvashi took a flat piece made of coins and, coating it with wax, bound it tight at her loins.","page":1451,"meaning_status":"draft","note":"ਟਕਿਯਨ ਕੀ ਚਪਟੀ ... ਮੋਮ ਮਾਰਿ ਆਸਨ ਸੌ ਕਸੀ: uncertain; understood as a false male member made of coins and wax and fastened at the seat, since the queen then takes Urvashi for a man."}]},{"type":"verse","number":[53],"number_text":"੫੩।","page":1451,"lines":[{"gurmukhi":"ਬਿਖਿ ਕੋ ਲੇਪ ਤਵਨ ਮੌ ਕੀਯੋ। ਸਿਵਹਿ ਰਿਝਾਇ ਮਾਂਗ ਕਰਿ ਲੀਯੋ।","roman":"Bikhi ko lep tavan mau keeyo | sivhi rijhaai maang kari leeyo |","meaning_en":"She smeared poison upon it, which she had obtained by pleasing Shiva and asking for it;","page":1451,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਕੇ ਅੰਗ ਤਵਨ ਸੌ ਲਾਗੈ। ਤਾ ਕੈ ਲੈ ਪ੍ਰਾਨਨ ਜਮ ਭਾਗੈ। ੫੩।","roman":"Jaa ke ang tavan sau laagai | taa kai lai praanan jam bhaagai | 53 |","meaning_en":"whoever's body it touched, Yama would take that one's life and be gone.","page":1451,"meaning_status":"draft"}]},{"type":"verse","number":[54],"number_text":"੫੪।","page":1451,"lines":[{"gurmukhi":"ਤਬ ਲੌ ਨਾਰਿ ਗਈ ਵਹੁ ਆਈ। ਕਾਮਾਤੁਰ ਹ੍ਵੈ ਕੈ ਲਪਟਾਈ।","roman":"Tab lau naari gaee vahu aaee | kaamaatur hvai kai laptaaee |","meaning_en":"By then that woman came, and overcome with desire she clung to her.","page":1451,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਕੋ ਭੇਦ ਕਛੂ ਨਹਿ ਜਾਨ੍ਯੋ। ਉਰਬਸਿ ਕੌ ਕਰਿ ਪੁਰਖ ਪਛਾਨ੍ਯੋ। ੫੪।","roman":"Taa ko bhed kachhoo nahi jaanyo | urabsi kau kari purakh pachhaanyo | 54 |","meaning_en":"She understood nothing of the secret, and took Urvashi for a man.","page":1451,"meaning_status":"draft"}]},{"type":"verse","number":[55],"number_text":"੫੫।","page":1451,"lines":[{"gurmukhi":"ਤਾ ਸੋ ਭੋਗ ਅਧਿਕ ਜਬ ਕੀਨੋ। ਮਨ ਮੈ ਮਾਨਿ ਅਧਿਕ ਸੁਖ ਲੀਨੋ।","roman":"Taa so bhog adhik jab keeno | man mai maani adhik sukh leeno |","meaning_en":"When she had made love with her to the full, and felt great pleasure in her heart,","page":1451,"meaning_status":"draft"},{"gurmukhi":"ਬਿਖੁ ਕੇ ਚੜੇ ਮਤ ਤਬ ਭਈ। ਜਮ ਕੇ ਧਾਮ ਬਿਖੈ ਚਲਿ ਗਈ। ੫੫।","roman":"Bikhu ke chare mat tab bhaee | jam ke dhaam bikhai chali gaee | 55 |","meaning_en":"then, as the poison rose, she grew senseless and went to the abode of Yama.","page":1451,"meaning_status":"draft"}]},{"type":"verse","number":[56],"number_text":"੫੬।","page":1451,"lines":[{"gurmukhi":"ਉਰਬਸਿ ਜਬ ਤਾ ਕੋ ਬਧ ਕੀਯੋ। ਸੁਰ ਪੁਰ ਕੋ ਮਾਰਗ ਤਬ ਲੀਯੋ।","roman":"Urabsi jab taa ko badh keeyo | sur pur ko maarag tab leeyo |","meaning_en":"When Urvashi had killed her, she took the road to the city of the gods.","page":1451,"meaning_status":"draft"},{"gurmukhi":"ਜਹਾ ਕਾਲ ਸੁਭ ਸਭਾ ਬਨਾਈ। ਉਰਬਸਿ ਯੌ ਚਲਿ ਕੈ ਤਹ ਆਈ। ੫੬।","roman":"Jahaa kaal subh sabhaa banaaee | urabsi yau chali kai tah aaee | 56 |","meaning_en":"Where Kaal had set up his fair court, there Urvashi came.","page":1451,"meaning_status":"draft"}]},{"type":"verse","number":[57],"number_text":"੫੭।","page":1451,"lines":[{"gurmukhi":"ਤਾ ਕੌ ਅਮਿਤ ਦਰਬੁ ਤਿਨ ਦੀਯੋ। ਮੇਰੋ ਬਡੋ ਕਾਮ ਤੁਮ ਕੀਯੋ।","roman":"Taa kau amit darbu tin deeyo | mero bado kaam tum keeyo |","meaning_en":"He gave her boundless wealth: 'You have done a great task for me;","page":1451,"meaning_status":"draft"},{"gurmukhi":"ਨਿਜੁ ਪਤਿ ਕੌ ਜਿਨ ਤ੍ਰਿਯਹਿ ਸੰਘਾਰਿਯੋ। ਤਾ ਕੋ ਤੈ ਇਹ ਭਾਤਿ ਪ੍ਰਹਾਰਿਯੋ। ੫੭।","roman":"Niju pati kau jin triyhi sanghaariyo | taa ko tai ih bhaati prahaariyo | 57 |","meaning_en":"the woman who killed her own husband, you have struck down in this way.'","page":1451,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1451,"meaning_status":"draft"},{"type":"verse","number":[58,1],"number_text":"੫੮। ੧।","page":1451,"lines":[{"gurmukhi":"ਜਾ ਦੁਖ ਤੇ ਜਿਨਿ ਇਸਤ੍ਰਿਯਹਿ ਨਿਜੁ ਪਤਿ ਹਨ੍ਯੋ ਰਿਸਾਇ।","roman":"Jaa dukh te jini istriyhi niju pati hanyo risaai |","meaning_en":"For the pain on account of which that woman in anger killed her own husband,","page":1451,"meaning_status":"draft","note":"ਦੁਖ: 'pain' (of the co-wife), as in verse 2."},{"gurmukhi":"ਤਿਸੀ ਦੋਖ ਮਾਰਿਯੋ ਤਿਸੈ ਧੰਨ੍ਯ ਧੰਨ੍ਯ ਜਮ ਰਾਇ। ੫੮। ੧।","roman":"Tisee dokh maariyo tisai dhanny dhanny jam raai | 58 | 1 |","meaning_en":"for that very fault she herself was killed; blessed, blessed is Yamrai.","page":1451,"meaning_status":"draft","note":"ਦੋਖ: 'fault'; the first line has ਦੁਖ 'pain'."}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਚਰਿਤ੍ਰ ਪਖ੍ਯਾਨੇ ਤ੍ਰਿਯਾ ਚਰਿਤ੍ਰੇ ਮੰਤ੍ਰੀ ਭੂਪ ਸੰਬਾਦੇ ਇਕ ਸੌ ਨੌ ਚਰਿਤ੍ਰ ਸਮਾਪਤਮ","roman":"Iti sree charitr pakhyaane triyaa charitre mantree bhoop sanbaade ik sau nau charitr samaaptam","meaning_en":"Thus ends the one hundred and ninth charitra of the Charitropakhyan, of the wiles of women, in the dialogue between the minister and the king,; complete.","page":1451,"meaning_status":"draft"},{"gurmukhi":"ਸਤੁ ਸੁਭਮ ਸਤੁ। ੧੦੯। ੨੦੮੩। ਅਫਜੂੰ।","roman":"Satu subham satu | 109 | 2083 | aphjoon |","meaning_en":"True, auspicious, true. 109. 2083. It continues.","page":1451,"meaning_status":"draft","note":"ਅਫਜੂੰ: Persian 'more, increasing', a closing formula."}],"page":1451,"number":[109,2083]}});
